package devdoc

import "encoding/json"

// EndpointField describes one merchant-supplied scalar parameter. Signing fields
// are generated by the documentation workbench and are not editable credentials.
type EndpointField struct {
	Name, Label, Type    string
	Required             bool
	Example, Description string
	Options              []string
}

// EndpointSpec is the public reference metadata for a V2 API operation.
type EndpointSpec struct {
	Slug, Title, Method, Path, Summary, Kind string
	Fields                                   []EndpointField
	ExampleResponse                          string
}

func field(name, label, kind, example, description string, required bool, options ...string) EndpointField {
	return EndpointField{Name: name, Label: label, Type: kind, Required: required, Example: example, Description: description, Options: options}
}

func example(value map[string]any) string {
	raw, _ := json.MarshalIndent(value, "", "  ")
	return string(raw)
}

func orderFields(fixture string) []EndpointField {
	return []EndpointField{
		field("out_trade_no", "商户订单号", "string", fixture, "沙箱查询固定样例 DOC_PAID / DOC_PENDING / DOC_REFUNDED / DOC_FROZEN / DOC_AUTH；演示下单不持久化。", false),
		field("trade_no", "平台订单号", "string", "", "与商户订单号二选一；非空时优先。沙箱使用相同的 DOC_ 样例编号。", false),
	}
}

func paymentFields() []EndpointField {
	return []EndpointField{
		field("out_trade_no", "商户订单号", "string", "DOC_NEW_ORDER", "商户内唯一的订单号；沙箱仅演示请求，不保存订单。", true),
		field("name", "商品名称", "string", "文档沙箱订单", "商品名称，服务按 UTF-8 边界截取至 127 字节。", false),
		field("money", "订单金额（元）", "amount", "1.00", "正十进制金额字符串，最多两位小数，不能使用浮点或科学计数法。", true),
		field("type", "支付方式", "string", "alipay", "示例支付方式，实际商户需开通对应通道。", true, "alipay", "wxpay"),
		field("notify_url", "异步通知地址", "url", "https://merchant.example.com/payments/notify", "沙箱只校验格式，不向该地址发请求。", false),
		field("return_url", "浏览器回跳地址", "url", "https://merchant.example.com/payments/return", "沙箱不会打开该地址。", false),
		field("param", "扩展参数", "string", "", "可选业务扩展字符串；不应放入密钥或个人敏感资料。", false),
	}
}

func submitFields() []EndpointField {
	fields := paymentFields()
	for i := range fields {
		if fields[i].Name == "type" {
			fields[i].Required = false
			fields[i].Description = "留空时进入收银台；沙箱只展示模拟跳转资料。"
			fields[i].Options = []string{"", "alipay", "wxpay"}
		}
	}
	return fields
}

