// EndpointForSlug resolves only the bounded published slug set; arbitrary paths
// and URLs cannot select another handler or destination.
func EndpointForSlug(slug string) *EndpointSpec {
	for _, spec := range EndpointSpecs() {
		if spec.Slug == slug {
			return &spec
		}
	}
	return nil
}

// EndpointSpecs returns owned copies so templates and callers cannot mutate the
// catalog used by subsequent anonymous sandbox requests.
func EndpointSpecs() []EndpointSpec {
	out := make([]EndpointSpec, len(endpointSpecs))
	copy(out, endpointSpecs)
	for i := range out {
		out[i].Fields = append([]EndpointField{}, out[i].Fields...)
		for j := range out[i].Fields {
			out[i].Fields[j].Options = append([]string(nil), out[i].Fields[j].Options...)
		}
	}
	return out
}
